PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS admission_form_applications (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), temporary_application_id TEXT NOT NULL UNIQUE, application_number TEXT NOT NULL UNIQUE, academic_year_id TEXT REFERENCES academic_years(id), term_id TEXT REFERENCES terms(id), application_date TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'ACCEPTED', 'REJECTED')), parent_user_id TEXT REFERENCES users(id), section1_candidate JSON NOT NULL, section2_history JSON NOT NULL, section3_guardians JSON NOT NULL, parent_declaration_accepted INTEGER NOT NULL DEFAULT 0, parent_signature_reference TEXT, parent_declaration_date TEXT, entrance_assessment_score NUMERIC(5,2) CHECK (entrance_assessment_score BETWEEN 0 AND 100), permanent_student_id TEXT UNIQUE, official_use JSON NOT NULL DEFAULT '{}', fee_snapshot JSON, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admission_documents (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES admission_form_applications(id), school_id TEXT NOT NULL REFERENCES schools(id), document_type TEXT NOT NULL, file_reference TEXT NOT NULL, uploaded_at TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, verified_by TEXT REFERENCES users(id), verified_at TEXT);
CREATE TABLE IF NOT EXISTS admission_fee_structures (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), level TEXT NOT NULL CHECK (level IN ('CRECHE_NURSERY', 'KINDERGARTEN', 'PRIMARY', 'JHS')), academic_year_id TEXT NOT NULL REFERENCES academic_years(id), term_id TEXT NOT NULL REFERENCES terms(id), tuition_academic_fee NUMERIC(12,2) NOT NULL CHECK (tuition_academic_fee >= 0), ict_lab_library_fee NUMERIC(12,2) NOT NULL CHECK (ict_lab_library_fee >= 0), pta_utility_charges NUMERIC(12,2) NOT NULL CHECK (pta_utility_charges >= 0), total_termly_fee NUMERIC(12,2) GENERATED ALWAYS AS (tuition_academic_fee + ict_lab_library_fee + pta_utility_charges) STORED, admission_registration_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (admission_registration_fee >= 0), school_uniform_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (school_uniform_fee >= 0), pe_kit_sportswear_fee NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (pe_kit_sportswear_fee >= 0), version INTEGER NOT NULL DEFAULT 1, is_published INTEGER NOT NULL DEFAULT 0, published_at TEXT, published_by TEXT REFERENCES users(id), publisher_role TEXT, updated_by TEXT REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, level, academic_year_id, term_id, version));
CREATE UNIQUE INDEX IF NOT EXISTS uq_admission_fee_active ON admission_fee_structures(school_id, level, academic_year_id, term_id) WHERE is_published = 1;
CREATE INDEX IF NOT EXISTS idx_admission_form_status ON admission_form_applications(school_id, status);
CREATE INDEX IF NOT EXISTS idx_admission_document_application ON admission_documents(school_id, application_id);
